// cephesini kapatır ama dünya sistemini değiştiren asıl an 11 Kasım'daki
// genel ateşkestir. Sevr (1920) dunya:4 — üç yıl içinde Lozan'la büyük
// ölçüde geçersiz kalacağı için kalıcı sistem değişikliği SAYILMADI.
