  d:"Asquith hükümetinin sunduğu üçüncü Home Rule tasarısı, 1911 Parlamento Yasası sayesinde Lordlar Kamarası'nın veto engelini aşarak yasalaşma yoluna girdi; ama Ulster Protestanlarının silahlı direniş tehdidi (Ulster Volunteer Force) ülkeyi bir iç savaşın eşiğine getirdi. Yasa 1914'te onaylandı ama I. Dünya Savaşı'nın patlak vermesiyle uygulaması savaş sonrasına ertelendi.",
